    {
        LogEntry[] logs = substate.Logs.Count != 0 ? substate.LogsToArray() : [];
        tracer.MarkAsSuccess(executingAccount, spentGas, substate.Output.AsReadOnlyArray(), logs, stateRoot);
    }
}

